import unittest
from solution import word_frequencies

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(word_frequencies("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(word_frequencies("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(word_frequencies(""), {})
    def test_punct(self):
        self.assertEqual(word_frequencies("a, a,"), {"a,": 2})
